function encodeBase62(num) {
  const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  if (num === 0) return chars[0];
  let result = '';
  while (num > 0) {
    result = chars[num % 62] + result;
    num = Math.floor(num / 62);
  }
  return result;
}

function generateShortCode(longUrl, salt = '') {
  const hash = sha256(longUrl + salt);
  // take the first 7 base62 style characters from the hash
  const code = hash.slice(0, 7);
  return code;
}

async function createShortLink(longUrl) {
  let salt = '';
  for (let attempt = 0; attempt < 5; attempt++) {
    const code = generateShortCode(longUrl, salt);
    const existing = await db.findByCode(code);
    if (!existing) {
      await db.insert({ code, longUrl, createdAt: Date.now() });
      return code;
    }
    salt = String(Math.random());
  }
  throw new Error('could not generate a unique code after 5 attempts');
}

